 private Path dir;private int phase,ticks;private long nonce=System.currentTimeMillis();private final long[] sent=new long[2];private final String[] names={"WBOne","WBTwo"};private ArcaneMerchant merchant;private final BlockPos table=new BlockPos(0,129,0);private UUID merchantId;private final Map<String,Object> results=new LinkedHashMap<>();
 private void check(boolean ok,String reason){if(!ok)throw new IllegalStateException(reason);}
 private void write(String name,Object value)throws Exception{var target=dir.resolve(name);var tmp=target.resolveSibling(name+".tmp");Files.writeString(tmp,new GsonBuilder().setPrettyPrinting().create().toJson(value));Files.move(tmp,target,StandardCopyOption.REPLACE_EXISTING,StandardCopyOption.ATOMIC_MOVE);}
